$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$packages=@(Get-AppxPackage -Name 'AnthropicPBC.Claude' -ErrorAction Stop)
if($packages.Count -ne 1){throw 'current-Claude-package-not-unique'}
$pkg=$packages[0]
$exe=Join-Path $pkg.InstallLocation 'app\claude.exe'
$asar=Join-Path $pkg.InstallLocation 'app\resources\app.asar'
$sig=Get-AuthenticodeSignature -LiteralPath $exe
$r=[ordered]@{schemaVersion=1;status='current-official-Store-Claude-registration-and-native-installed-files-readonly';observedAtUtc=[DateTime]::UtcNow.ToString('o');actualNativeExitCode=0;registeredPackageName=$pkg.Name;registeredPackageVersion=$pkg.Version.ToString();registeredPackageFullName=$pkg.PackageFullName;registeredPackageFamilyName=$pkg.PackageFamilyName;registeredPackageStatus=$pkg.Status.ToString();registeredPackageSignatureKind=$pkg.SignatureKind.ToString();installedExeBytes=(Get-Item -LiteralPath $exe).Length;installedExeSha256=(Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash.ToLowerInvariant();installedExeAuthenticodeStatus=$sig.Status.ToString();installedExeSignerSimpleName=$sig.SignerCertificate.GetNameInfo([Security.Cryptography.X509Certificates.X509NameType]::SimpleName,$false);installedExeSignerThumbprint=$sig.SignerCertificate.Thumbprint;installedExeFileVersion=(Get-Item -LiteralPath $exe).VersionInfo.FileVersion;installedExeProductVersion=(Get-Item -LiteralPath $exe).VersionInfo.ProductVersion;installedAsarBytes=(Get-Item -LiteralPath $asar).Length;installedAsarSha256=(Get-FileHash -LiteralPath $asar -Algorithm SHA256).Hash.ToLowerInvariant();priorInstallationProofSha256=(Get-FileHash -LiteralPath (Join-Path $PSScriptRoot 'installed-windows-native-final-safe.json') -Algorithm SHA256).Hash.ToLowerInvariant();privateProfileContentsRead=$false;installationOperations=0;GUIActions=0;processSignals=0;modelOrAuthenticationCalls=0}
if($r.registeredPackageVersion -cne '5.11492.5.0' -or $r.registeredPackageStatus -cne 'Ok' -or $r.registeredPackageSignatureKind -cne 'Store' -or $r.installedExeSha256 -cne '093fb6529006fe5fbe28b61231484734dab78a497dc1b05311f2315590118414' -or $r.installedAsarSha256 -cne '47433b3c91cdbc813de9d277dfb5b0fbc21d17a7b3a49528e07ef1edc0935ed2' -or $r.installedExeAuthenticodeStatus -cne 'Valid' -or $r.installedExeSignerSimpleName -cne 'Anthropic, PBC'){throw 'current-installed-native-package-verification-failed'}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'current-registered-installed-proof-safe.json'),(ConvertTo-Json -InputObject $r -Depth 8)+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))
$r|ConvertTo-Json -Depth 8
